   IF r.constraint_type<>''C'' OR NOT REGEXP_LIKE(compact(r.search_condition_vc),''^[A-Z][A-Z0-9_$]*ISNOTNULL$'') THEN
    meaningful_constraints:=meaningful_constraints+1;
