   IF app_id IS NOT NULL OR app_user IS NOT NULL THEN
     native_identity(p_scope,p_subject,account);pinned:=apex_util.');
 l_step:=l_step||TO_CLOB('get_session_state(''''KCV_AUTH_ACCOUNT_ID'''');
     IF pinned IS NULL OR pinned<>account THEN
