  SELECT COUNT(*) INTO n FROM user_errors WHERE name=p_name AND type=p_type AND attribute=''ERROR'';
  require(n=0,''Compilation errors: ''||p_name||'' ''||p_type);
  FOR r IN(SELECT text FROM user_source WHERE nam');
