  require(actual_hash=p_sha256,''Installed source digest differs: ''||p_name||'' ''||p_type);
 EXCEPTION WHEN OTHERS THEN
  IF DBMS_LOB.ISTEMPORARY(source_text)=1 THEN DBMS_LOB.FREETEMPORARY(source_text);END IF;RAISE;
 END;
